require_once __DIR__.'/../includes/account.php';account_schema();$u=require_account();$pdo=db();$recent=$pdo->prepare('SELECT activity,created_at FROM account_activity WHERE user_id=? ORDER BY id DESC LIMIT 8');$recent->execute([$u['id']]);$logs=$recent->fetchAll();
$counts=['Businesses'=>0,'Talent profiles'=>0,'Course enrolments'=>0];
