my.php">Explore courses</a><?php endif;?><a href="../modules/directory.php">Explore businesses</a><a href="../modules/talent.php">Explore talents</a><a href="../modules/academy.php">Explore academy</a><a href="../modules/services.php">Request digital service</a></div><div class="dash-card"><h2>Recent account activity</h2><?php if(!$logs):?><p class="muted">Your activity will appear here.</p><?php else:?><ul><?php foreach($logs as $log):?><li><?=e($log['activity'])?> <span class="muted">· <?=e($log['created_at'])?></span></li><?php endforeach;?></ul><?php endif;?></div><p class="muted">Plateau Digital · Discover. Connect. Learn. Grow.</p></main></body></html>
